{
  "name": "罗德与施瓦茨网络测试仪器",
  "name_en": "Rohde & Schwarz networked test instrument",
  "manufacturer": "Rohde & Schwarz",
  "description": "通过以太网 Socket/VISA 接口通信的罗德与施瓦茨电子测试仪器。该类设备通常用于实验室中的远程配置、状态查询、数据读取和自动化测量，常见于射频与通用电子测试场景。",
  "description_en": "A Rohde & Schwarz electronic test instrument that communicates through an Ethernet socket/VISA interface. Such instruments are commonly used in laboratories for remote configuration, status queries, data readout, and automated measurements in RF and general electronic test setups.",
  "tag_hints": [
    "Rohde & Schwarz",
    "SCPI control",
    "Ethernet socket instrument",
    "VISA communication",
    "electronic test equipment",
    "automated measurement"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与仪器的网络会话。",
      "description_en": "Close the network session to the instrument."
    },
    {
      "action_name": "auto-open",
      "description": "通过指定 IP 地址和端口打开与仪器的原始 Socket 连接。",
      "description_en": "Open a raw socket connection to the instrument using the specified IP address and port."
    },
    {
      "action_name": "auto-query",
      "description": "向仪器发送 SCPI 查询命令并读取返回结果。",
      "description_en": "Send an SCPI query command to the instrument and read back the response."
    },
    {
      "action_name": "auto-timeout",
      "description": "设置与仪器通信的超时时间。",
      "description_en": "Set the communication timeout for the instrument connection."
    },
    {
      "action_name": "auto-read_raw",
      "description": "从仪器读取原始二进制数据。",
      "description_en": "Read raw binary data from the instrument."
    },
    {
      "action_name": "auto-write",
      "description": "向仪器发送 SCPI 命令。",
      "description_en": "Send an SCPI command to the instrument."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向仪器发送原始数据或原始命令字符串。",
      "description_en": "Send raw data or a raw command string to the instrument."
    }
  ]
}

